public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    Vec3 start = entity.getEyePosition();
    Vec3 end = start.add(entity.getForward().normalize().scale(80));
    HitResult hitResult = RaycastBuilder.begin(entity.level, entity)
            .start(start)
            .end(end)
            .checkForBlocks(true)
            .bbInflation(0.35f)
            .filter(Utils::validAntiMagicTarget)
            .build();
    Vec3 forward = entity.getForward().normalize();
    if (hitResult instanceof EntityHitResult entityHitResult) {
        var hitEntity = entityHitResult.getEntity();
        if (!(NeoForge.EVENT_BUS.post(new CounterSpellEvent(entity, hitEntity)).isCanceled())) {
            if (hitEntity instanceof AntiMagicSusceptible antiMagicSusceptible) {
                if (antiMagicSusceptible instanceof IMagicSummon summon) {
                    if (summon.getSummoner() == entity) {
                        if (summon instanceof Mob mob && mob.getTarget() == null) {
                            antiMagicSusceptible.onAntiMagic(playerMagicData);
                        }
                    } else {
                        antiMagicSusceptible.onAntiMagic(playerMagicData);
                    }
                } else {
                    antiMagicSusceptible.onAntiMagic(playerMagicData);
                }
            } else if (hitEntity instanceof ServerPlayer serverPlayer) {
                Utils.serverSideCancelCast(serverPlayer, true);
                MagicData.getPlayerMagicData(serverPlayer).getPlayerRecasts().removeAll(RecastResult.COUNTERSPELL);
            } else if (hitEntity instanceof IMagicEntity abstractSpellCastingMob) {
                abstractSpellCastingMob.cancelCast();
            }
            if (hitEntity instanceof LivingEntity livingEntity) {
                //toList to avoid concurrent modification
                for (Holder<MobEffect> mobEffect : livingEntity.getActiveEffectsMap().keySet().stream().toList()) {
                    if (mobEffect.value() instanceof MagicMobEffect) {
                        livingEntity.removeEffect(mobEffect);
                    }
                }
            }
        }
    }
    double distance = entity.position().distanceTo(hitResult.getLocation());
    for (float i = 1; i < distance; i += .5f) {
        Vec3 pos = entity.getEyePosition().add(forward.scale(i));
        MagicManager.spawnParticles(world, ParticleTypes.ENCHANT, pos.x, pos.y, pos.z, 1, 0, 0, 0, 0, false);
    }
    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

public HitResult performRaycast() {
    Objects.requireNonNull(start, "Start must be set to perform raycast");
    Objects.requireNonNull(end, "End must be set to perform raycast");

    BlockHitResult blockHitResult = null;
    Vec3 rayEnd = end;

    if (checkForBlocks) {
        blockHitResult = level.clip(new ClipContext(start, end, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, originEntity));
        rayEnd = blockHitResult.getLocation();
    }

    AABB range = originEntity.getBoundingBox().expandTowards(rayEnd.subtract(start));
    List<HitResult> hits = new ArrayList<>();
    List<? extends Entity> entities = level.getEntities(originEntity, range, filter);

    for (Entity target : entities) {
        HitResult hit = Utils.checkEntityIntersecting(target, start, rayEnd, bbInflation);
        if (hit.getType() != HitResult.Type.MISS) {
            hits.add(hit);
        }
    }

    if (!hits.isEmpty()) {
        hits.sort(Comparator.comparingDouble(o -> o.getLocation().distanceToSqr(start)));
        return hits.get(0);
    }
    if (checkForBlocks) {
        return blockHitResult;
    } else {
        return BlockHitResult.miss(rayEnd, Direction.UP, BlockPos.containing(rayEnd));
    }
}

public static boolean validAntiMagicTarget(Entity entity) {
    return !entity.isSpectator() && (entity instanceof AntiMagicSusceptible || (entity instanceof Player) || (entity instanceof IMagicEntity));
}

package io.redspace.ironsspellbooks.api.events;

import net.minecraft.world.entity.Entity;
import net.neoforged.bus.api.Event;
import net.neoforged.bus.api.ICancellableEvent;

public class CounterSpellEvent extends Event implements ICancellableEvent {
    public final Entity caster;
    public final Entity target;

    public CounterSpellEvent(Entity caster, Entity target) {
        this.caster = caster;
        this.target = target;
    }
}

default Entity getSummoner() {
    return SummonManager.getOwner((Entity) this);
}

public static @Nullable Entity getOwner(@NotNull Entity summon) {
    if (summon.level instanceof ServerLevel serverLevel) {
        if (INSTANCE.summonToOwner.containsKey(summon.getUUID())) {
            return serverLevel.getEntity(INSTANCE.summonToOwner.get(summon.getUUID()));
        }
    }
    return null;
}

default void onAntiMagic(MagicData playerMagicData) {
    onUnSummon();
}

public void onUnSummon() {
    if (!level().isClientSide) {
        MagicManager.spawnParticles(level(), ParticleTypes.POOF, getX(), getY(), getZ(), 25, .4, .8, .4, .03, false);
        setRemoved(RemovalReason.DISCARDED);
    }
}

private static Supplier<AbstractSpell> registerSpell(AbstractSpell spell) {
    return SPELLS.register(spell.getSpellName(), () -> spell);
}

public static void handleClientBoundOnCastFinished(UUID castingEntityId, String spellId, boolean cancelled) {
    ClientMagicData.resetClientCastState(castingEntityId);
    var player = Minecraft.getInstance().player.level.getPlayerByUUID(castingEntityId);

    var spell = SpellRegistry.getSpell(spellId);


    var finishAnimation = spell.getCastFinishAnimation();

    if (finishAnimation.getForPlayer().isPresent() && !cancelled) {
        AnimationHelper.animatePlayerStart(player, finishAnimation.getForPlayer().get());
    } else if (finishAnimation != AnimationHolder.pass() || cancelled) {
        AnimationHelper.cancelPlayerAnimation((AbstractClientPlayer) player);
    }

    if (cancelled && spell.stopSoundOnCancel()) {
        spell.getCastStartSound().ifPresent((soundEvent) -> Minecraft.getInstance().getSoundManager().stop(soundEvent.getLocation(), null));
    }

    if (castingEntityId.equals(Minecraft.getInstance().player.getUUID()) && ClientInputEvents.isUseKeyDown()) {
        ClientInputEvents.hasReleasedSinceCasting = false;
    }
}

