public static void cancelPlayerAnimation(AbstractClientPlayer player) {
    var animation = (ModifierLayer<IAnimation>) PlayerAnimationAccess.getPlayerAssociatedData(player).get(SpellAnimations.ANIMATION_RESOURCE);
    if (animation != null) {
        animation.replaceAnimationWithFade(AbstractFadeModifier.standardFadeIn(4, Ease.INOUTSINE), null, false);
        IronsAdjustmentModifier.INSTANCE.fadeOut(5);
    }
}

public static void sendBatchesDetached(Entity sourceEntity, List<ParticleGroup> effects) {
    if (effects == null || effects.isEmpty()) {
        return;
    }
    ArrayList<Packets.ParticleEffects.Spawn> spawns = new ArrayList<>();
    for (var effect : effects) {
        // Origins and orientation resolved server-side, exactly like the ENTITY source type.
        // The entity id is still included so entity-bound particle resolution keeps working
        // when the entity is present.
        spawns.add(new Packets.ParticleEffects.Spawn(
                sourceEntity.getId(),
                sourceEntity.getYaw(),
                sourceEntity.getPitch(),
                origin(sourceEntity, effect.batch), effect));
    }
    var packet = new Packets.ParticleEffects(Packets.ParticleEffects.SourceType.COORDINATE, 1, spawns);
    if (sourceEntity instanceof ServerPlayerEntity serverPlayer) {
        if (Platform.util().networkS2C_CanSend(serverPlayer, Packets.ParticleEffects.ID)) {
            Platform.util().networkS2C_Send(serverPlayer, packet);
        }
    }
    Platform.tracking(sourceEntity).forEach(serverPlayer -> {
        if (Platform.util().networkS2C_CanSend(serverPlayer, Packets.ParticleEffects.ID)) {
            Platform.util().networkS2C_Send(serverPlayer, packet);
        }
    });
}

public static boolean lookupAndPerformAreaImpact(Spell.AreaImpact area_impact, RegistryEntry<Spell> spellEntry, LivingEntity caster, Entity exclude, @Nullable Entity aoeSource,
                                              List<Spell.Impact> impacts, ImpactContext context, boolean additionalTargetLookup, @Nullable Float radiusOverride) {
    var center = context.position();
    var radius = radiusOverride != null ? radiusOverride : area_impact.combinedRadius(context.power().baseValue());

    var contextEntity = aoeSource != null ? aoeSource : caster;
    var targets = TargetHelper.targetsFromArea(contextEntity.getWorld(), aoeSource, center, contextEntity.getRotationVector(), radius, area_impact.area, null);
    if (exclude != null) {
        targets.remove(exclude);
    }
    var result = applyAreaImpact(contextEntity.getWorld(), caster, targets, radius, area_impact.area, spellEntry, impacts,
            context.target(SpellTarget.FocusMode.AREA), additionalTargetLookup, area_impact.execute_action_type);
    var areaVisuals = area_impact.visuals.resolved(Fx.Context.NONE);
    if (aoeSource != null) {
        // Anchored by coordinates rather than entity id: the source entity may die this very
        // tick (e.g. a falling projectile finishing), and entity-anchored FX would re-resolve
        // against its client-side position — racing the removal packet and placing the FX
        // wherever the client's own simulation of the entity happens to be.
        ParticleHelper.sendBatchesDetached(aoeSource, areaVisuals.particles);
    } else {
        ParticleHelper.sendBatches(center, caster, areaVisuals.particles);
    }

    SoundHelper.playSound(contextEntity.getWorld(), contextEntity, area_impact.sound);
    ModelEffectHelper.spawn(contextEntity.getWorld(), center, caster.getYaw(), areaVisuals.models,
            contextEntity instanceof LivingEntity le ? le : null);
    return result;
}

protected void onImpactPerformed(LivingEntity owner, World world, Spell.Delivery.Cloud cloudData, SpellExecution.ImpactContext context) {
    // Server-side call site: `ParticleHelper.play` bottoms out in `World.addParticle`, which is an
    // empty method on anything but ClientWorld — it has to be broadcast instead. Detached (rather
    // than entity-anchored) because a cloud whose `despawn_ticks` is 0 is discarded on this very
    // tick, and the client would resolve the packet's entity id to nothing.
    ParticleHelper.sendBatchesDetached(this, cloudData.impact.resolved(Fx.Context.NONE).particles);
    this.impactsPerformed++;
}

public record ParticleEffects(SourceType sourceType, float countMultiplier, List<Spawn> spawns) implements CustomPayload {
    public static Identifier ID = Identifier.of(SpellEngineMod.ID, "particle_effects");
    public static final CustomPayload.Id<ParticleEffects> PACKET_ID = new CustomPayload.Id<>(ID);
    public static final PacketCodec<RegistryByteBuf, ParticleEffects> CODEC = PacketCodec.of(ParticleEffects::write, ParticleEffects::read);
    @Override
    public Id<? extends CustomPayload> getId() {
        return PACKET_ID;
    }

    public enum SourceType { ENTITY, COORDINATE }
    public record Spawn(int sourceEntityId, float yaw, float pitch, Vec3d sourceLocation, ParticleGroup effect) { }

    // The effect ships as GSON (same as `SpellContainerSync`): self-describing named
    // fields, so enums are no longer serialized by ordinal and none of them is
    // append-only. `countMultiplier` is a real packet field applied at spawn time,
    // instead of being baked into the counts at write time.
    private static final Gson gson = new Gson();

    public void write(RegistryByteBuf buffer) {
        buffer.writeInt(sourceType.ordinal());
        buffer.writeFloat(countMultiplier);
        buffer.writeInt(spawns.size());
        for (var spawn: spawns) {
            buffer.writeInt(spawn.sourceEntityId);
            buffer.writeFloat(spawn.yaw);
            buffer.writeFloat(spawn.pitch);
            buffer.writeDouble(spawn.sourceLocation.x);
            buffer.writeDouble(spawn.sourceLocation.y);
            buffer.writeDouble(spawn.sourceLocation.z);
            buffer.writeString(gson.toJson(spawn.effect));
        }
    }

    public static ParticleEffects read(RegistryByteBuf buffer) {
        var sourceType = SourceType.values()[buffer.readInt()];
        var countMultiplier = buffer.readFloat();
        var spawnCount = buffer.readInt();
        var spawns = new ArrayList<Spawn>();
        for (int i = 0; i < spawnCount; ++i) {
            spawns.add(new Spawn(
                    buffer.readInt(),
                    buffer.readFloat(),
                    buffer.readFloat(),
                    new Vec3d(buffer.readDouble(), buffer.readDouble(), buffer.readDouble()),
                    gson.fromJson(buffer.readString(), ParticleGroup.class)
            ));
        }
        return new ParticleEffects(sourceType, countMultiplier, spawns);
    }
}

public static void init() {
    // Config stage
    PayloadTypeRegistry.configurationS2C().register(Packets.ConfigSync.PACKET_ID, Packets.ConfigSync.CODEC);
    PayloadTypeRegistry.configurationS2C().register(Packets.SpellRegistrySync.PACKET_ID, Packets.SpellRegistrySync.CODEC);
    PayloadTypeRegistry.configurationC2S().register(Packets.Ack.PACKET_ID, Packets.Ack.CODEC);

    ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
        // This if block is required! Otherwise the client gets stuck in connection screen
        // if the client cannot handle the packet.
        if (ServerConfigurationNetworking.canSend(handler, Packets.ConfigSync.ID)) {
            handler.addTask(new ConfigurationTask(SpellEngineMod.config));
        } else {
            handler.disconnect(Text.literal("Network configuration task not supported: " + ServerNetwork.CONFIG_TASK_NAME));
        }
    });
    ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
        if (ServerConfigurationNetworking.canSend(handler, Packets.SpellRegistrySync.ID)) {
            if (SpellAssignments.encoded.isEmpty()) {
                throw new AssertionError("Spell registry is empty!");
            }
            handler.addTask(new SpellRegistrySyncTask(SpellAssignments.encoded));
        } else {
            handler.disconnect(Text.literal("Network configuration task not supported: " + ServerNetwork.SPELL_REGISTRY_TASK_NAME));
        }
    });
    ServerConfigurationNetworking.registerGlobalReceiver(Packets.Ack.PACKET_ID, (packet, context) -> {
        // Warning: if you do not call completeTask, the client gets stuck!
        if (packet.code().equals(ServerNetwork.CONFIG_TASK_NAME)) {
            context.networkHandler().completeTask(ConfigurationTask.KEY);
        }
        if (packet.code().equals(ServerNetwork.SPELL_REGISTRY_TASK_NAME)) {
            context.networkHandler().completeTask(SpellRegistrySyncTask.KEY);
        }
    });

    // Play stage
    PayloadTypeRegistry.playC2S().register(Packets.CastRequest.PACKET_ID, Packets.CastRequest.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.TargetStream.PACKET_ID, Packets.TargetStream.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.CastInput.PACKET_ID, Packets.CastInput.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.AttackPerform.PACKET_ID, Packets.AttackPerform.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.AttackFxBroadcast.PACKET_ID, Packets.AttackFxBroadcast.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellCooldown.PACKET_ID, Packets.SpellCooldown.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellCooldownSync.PACKET_ID, Packets.SpellCooldownSync.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellMessage.PACKET_ID, Packets.SpellMessage.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.ParticleEffects.PACKET_ID, Packets.ParticleEffects.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellAnimation.PACKET_ID, Packets.SpellAnimation.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellContainerSync.PACKET_ID, Packets.SpellContainerSync.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.AttackAvailable.PACKET_ID, Packets.AttackAvailable.CODEC);

    ServerPlayNetworking.registerGlobalReceiver(Packets.CastRequest.PACKET_ID, (packet, context) ->
            ServerNetwork.handleCastRequest(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.TargetStream.PACKET_ID, (packet, context) ->
            ServerNetwork.handleTargetStream(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.CastInput.PACKET_ID, (packet, context) ->
            ServerNetwork.handleCastInput(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.AttackFxBroadcast.PACKET_ID, (packet, context) ->
            ServerNetwork.handleAttackFxBroadcast(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.AttackPerform.PACKET_ID, (packet, context) ->
            ServerNetwork.handleAttackPerform(packet, context.server(), context.player()));
}

