protected void beginDespawn(int ticks) {
    if (getWorld().isClient || isDespawning()) {
        return;
    }
    if (ticks <= 0) {
        this.discard();
        return;
    }
    this.despawnDuration = ticks;
    this.timeToLive = this.age + ticks;
    // Publish now; waiting for the next tick would leak one frame of the ACTIVE pose.
    setPhase(PHASE_DESPAWNING);
}

public static boolean deliver(World world, RegistryEntry<Spell> spellEntry, LivingEntity caster, List<DeliveryTarget> targets, ImpactContext context,
                              @Nullable Vec3d targetLocation, @Nullable Consumer<DeliveryCompletion> completion, boolean forceSuccess, boolean scheduled) {
    var spell = spellEntry.value();

    if (spell.deliver.delay > 0) {
        if (scheduled) {
            Predicate<Entity> validator = (entity) -> !(entity == null || entity.isRemoved());
            if (!validator.test(caster)) {
                return false;
            }
            targets = targets.stream().filter(target -> validator.test(target.entity())).toList();
        } else {
            List<DeliveryTarget> finalTargets = targets;
            ((WorldScheduler) world).schedule(spell.deliver.delay, () -> deliver(world, spellEntry, caster, finalTargets, context, targetLocation, completion, forceSuccess, true));
            return true;
        }
    }

    var delivered = false;
    switch (spell.deliver.type) {
        case DIRECT -> {
            var anySuccess = false;
            var casterPos = caster.getPos().add(0, caster.getHeight() / 2F, 0);
            if (targets.isEmpty() && targetLocation != null
                    && spell.area_impact != null) { // Special check to allow area impacts only, in the absence of targets
                var position = targetLocation.lerp(casterPos, 0.001F);
                var targetSpecificContext = context.position(position);
                SpellImpacts.performImpacts(world, caster, caster, null, spellEntry, spell.impacts, targetSpecificContext);
                anySuccess = true; // The area impact will be executed, hence always true
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var position = target == caster
                            ? casterPos
                            : target.getPos().add(0, target.getHeight() / 2F, 0).lerp(casterPos, 0.01F);
                    var targetSpecificContext = targeted.context().position(position);
                    var result = SpellImpacts.performImpacts(world, caster, target, target, spellEntry, spell.impacts, targetSpecificContext);
                    anySuccess = anySuccess || result;
                }
            }
            delivered = anySuccess;
        }
        case PROJECTILE -> {
            if (targets.isEmpty()) {
                ProjectileLauncher.shootProjectile(world, caster, null, spellEntry, context);
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var targetSpecificContext = targeted.context();
                    ProjectileLauncher.shootProjectile(world, caster, target, spellEntry, targetSpecificContext);
                }
            }
            delivered = true;
        }
        case METEOR -> {
            var anyLaunched = false;
            if (targets.isEmpty() && targetLocation != null) {
                ProjectileLauncher.fallProjectile(world, caster, null, targetLocation, spellEntry, context);
                anyLaunched = true;
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var targetSpecificContext = targeted.context();
                    ProjectileLauncher.fallProjectile(world, caster, target, null, spellEntry, targetSpecificContext);
                    anyLaunched = true;
                }
            }
            delivered = anyLaunched;
        }
        case CLOUD -> {
            var placedAny = false;
            if (targets.isEmpty() && targetLocation != null) {
                CloudPlacer.placeCloud(world, caster, null, targetLocation, spellEntry, context.position(targetLocation));
                placedAny = true;
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var targetSpecificContext = targeted.context();
                    CloudPlacer.placeCloud(world, caster, target, null, spellEntry, targetSpecificContext);
                    placedAny = true;
                }
            }
            delivered = placedAny;
        }
        case SHOOT_ARROW -> {
            ArrowHelper.shootArrow(world, caster, spellEntry, context);
            delivered = true;
        }
        case AFFECT_ARROW -> {
            if (caster instanceof SpellCaster.Player shooter) {
                var arrowContext = shooter.getArrowShootContext();
                arrowContext.activeSpells.add(spellEntry);
            }
            delivered = true;
        }
        case MELEE -> {
            if (spell.deliver.melee != null
                    && !spell.deliver.melee.attacks.isEmpty()) {
                var attackers = !targets.isEmpty()
                        ? targets.stream().map(e -> e.entity()).toList()
                        : List.of(caster);
                var meleeData = spell.deliver.melee;
                var spellId = spellEntry.getKey().get().getValue();
                var attacks = meleeData.attacks;
                if (context.isChanneled()) {
                    var index = context.channelTickIndex() % attacks.size();
                    attacks = List.of(attacks.get(index));
                }
                for (var attacker: attackers) {
                    if (!attacker.isOnGround() && !spell.deliver.melee.allow_airborne) {
                        break;
                    }
                    if (attacker instanceof ServerPlayerEntity serverPlayer) {
                        // Map to resolved MeleeAttack structures
                        var meleeAttacks = Melee.createMeleeAttacks(serverPlayer, attacks, spellEntry,
                                context.charge(), context.chargeModifier());
                        // Send AttackAvailable packet to client
                        var packet = new Packets.AttackAvailable(spellId, meleeAttacks);
                        Platform.util().networkS2C_Send(serverPlayer, packet);
                        delivered = true;
                    }
                }
            }
        }
        case STASH_EFFECT -> {
            var anyAdded = false;
            var stash = spell.deliver.stash_effect;
            var id = Identifier.of(stash.id);
            var effect = Registries.STATUS_EFFECT.getEntry(id).get();

            var amplifier = stash.amplifier;
            if (stash.amplifier_power_multiplier != 0) {
                var power = SpellPower.getSpellPower(spell.school, caster);
                amplifier += (int)(stash.amplifier_power_multiplier * power.nonCriticalValue());
            }
            for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
                amplifier += modifier.stash_amplifier_add;
            }
            for (var targeted: targets) {
                if (targeted.entity() instanceof LivingEntity livingEntity) {
                    if (stash.stacking) {
                        var stack = -1;
                        var existingInstance = livingEntity.getStatusEffect(effect);
                        if (existingInstance != null) {
                            stack = existingInstance.getAmplifier();
                            livingEntity.removeStatusEffect(effect);
                        }
                        stack += 1;
                        var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), Math.min(stack, amplifier), false, stash.show_particles, true);
                        livingEntity.addStatusEffect(instance);
                    } else {
                        var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), amplifier, false, stash.show_particles, true);
                        livingEntity.addStatusEffect(instance);
                    }
                    anyAdded = true;
                }
            }
            delivered = anyAdded;
        }
        case CUSTOM -> {
            if (spell.deliver.custom != null) {
                var handler = SpellHandlers.customDelivery.get(spell.deliver.custom.handler);
                if (handler != null) {
                    delivered = handler.onSpellDelivery(world, spellEntry, caster, targets, context, targetLocation);
                }
            }
        }
    }

    if (completion != null) {
        completion.accept(new DeliveryCompletion(delivered || forceSuccess));
    }

    return delivered;
}

public static void placeCloud(World world, LivingEntity caster,
                              @Nullable Entity target, @Nullable Vec3d location,
                              RegistryEntry<Spell> spellEntry, ImpactContext context) {
    var spell = spellEntry.value();
    var clouds = spell.deliver.clouds;
    if (clouds == null || clouds.isEmpty()) {
        return;
    }
    if (target == null && location == null) {
        target = caster;
    }

    List<Spell.Modifier> spellModifiers = SpellModifiers.of(caster, spellEntry, context.chargeModifier());
    float extraTimeToLive = 0;
    var extraPlacements = new ArrayList<Spell.EntityPlacement>();
    // Summed cloud bonus, snapshotted onto each cloud below. Magnitudes accumulate; growth timing is
    // taken from the first modifier that actually contributes growth (see radiusForAge merge rules).
    var cloudModifier = new Spell.Modifier.Cloud();
    boolean cloudTimingSet = false;
    for (var spellModifier: spellModifiers) {
        extraTimeToLive += spellModifier.spawn_duration_add;
        extraPlacements.addAll(spellModifier.additional_placements);
        var cm = spellModifier.cloud;
        if (cm != null) {
            cloudModifier.radius_add += cm.radius_add;
            cloudModifier.growth.radius_step += cm.growth.radius_step;
            if (cm.growth.duration_ticks < 0 || cloudModifier.growth.duration_ticks < 0) {
                cloudModifier.growth.duration_ticks = -1; // "whole life" sentinel wins over any span
            } else {
                cloudModifier.growth.duration_ticks += cm.growth.duration_ticks;
            }
            if (!cloudTimingSet && cm.growth.radius_step != 0F) {
                cloudModifier.growth.step_interval = cm.growth.step_interval;
                cloudModifier.growth.start_tick = cm.growth.start_tick;
                cloudTimingSet = true;
            }
        }
    }

    var index = 0;
    for (var cloud: clouds) {
        var placements = new ArrayList<Spell.EntityPlacement>();
        placements.add(cloud.placement);
        placements.addAll(cloud.additional_placements);
        if (index == 0) {
            placements.addAll(extraPlacements);
        }
        var base_delay = cloud.delay_ticks;

        for (var placement: placements) {
            var delay = base_delay + placement.delay_ticks;

            SpellCloud entity;
            if (cloud.entity_type_id != null) {
                var id = Identifier.of(cloud.entity_type_id);
                var type = Registries.ENTITY_TYPE.get(id);
                entity = (SpellCloud) type.create(world);
            } else {
                entity = new SpellCloud(world);
            }
            entity.setOwner(caster);
            entity.onCreatedFromSpell(spellEntry.getKey().get().getValue(), cloud, context, cloud.time_to_live_seconds + extraTimeToLive, cloudModifier);

            if (target != null) {
                EntityPlacements.applyEntityPlacement(entity, target, target.getPos(), placement);
            } else if (location != null) {
                EntityPlacements.applyEntityPlacement(caster.getWorld(), entity,
                        caster.getYaw(), caster.getPitch(), null,
                        location, placement);
            } else {
                continue;
            }


            ((WorldScheduler)world).schedule(delay, () -> {
                world.spawnEntity(entity);
                var sound = cloud.spawn.sound;
                if (sound != null) {
                    SoundHelper.playSound(world, entity, sound);
                }
                var spawnVisuals = cloud.spawn.visuals.resolved(Fx.Context.NONE);
                ParticleHelper.sendBatches(entity, spawnVisuals.particles);
                ModelEffectHelper.spawn(world, entity.getPos(), entity.getYaw(), spawnVisuals.models, null);
            });

            if (cloud.placement_delay_stacks) {
                base_delay = delay;
            }
        }
        index += 1;
    }
}

public void onCreatedFromSpell(Identifier spellId, Spell.Delivery.Cloud cloudData, SpellExecution.ImpactContext context, float time_to_live_seconds, Spell.Modifier.Cloud cloudModifier) {
    this.spellId = spellId;
    this.context = context;
    this.cloudModifier = cloudModifier;

    var spellEntry = getSpellEntry();
    if (spellEntry != null) {
        var spell = spellEntry.value();
        var index = 0;
        var dataList = spell.deliver.clouds;
        if (!dataList.isEmpty()) {
            index = dataList.indexOf(cloudData);
        }
        this.dataIndex = index;
    }
    this.getDataTracker().set(SPELL_ID_TRACKER, this.spellId.toString());
    this.getDataTracker().set(DATA_INDEX_TRACKER, this.dataIndex);
    this.getDataTracker().set(RADIUS_TRACKER, radiusForAge(this.age));

    // Carve the lifetime into spawning / active / despawning, like a summoned entity.
    // `time_to_live_seconds` is the ACTIVE duration; spawn/despawn bracket it.
    this.spawnDuration   = cloudData.spawn_ticks;
    this.despawnDuration = cloudData.despawn_ticks;
    int activeTicks      = (int) (time_to_live_seconds * 20);
    this.timeToLive      = this.spawnDuration + activeTicks + this.despawnDuration;
    this.impactCap = cloudData.impact_cap;
}

public void tick() {
    super.tick();
    var cloudData = this.getCloudData();
    if (cloudData == null) {
        // this.discard();
        return;
    }
    var world = this.getWorld();
    if (world.isClient) {
        // Client side tick
        float trackedRadius = getDataTracker().get(RADIUS_TRACKER);
        if (spawnRenderRadius < 0F) {
            spawnRenderRadius = prevRenderRadius = renderRadius = trackedRadius;
        } else {
            prevRenderRadius = renderRadius;
            renderRadius = trackedRadius;
        }
        setupAnimationStates();
        var clientData = cloudData.client_data;
        var spawnParticles = clientData.particle_spawn_interval <= 1 || (this.age % clientData.particle_spawn_interval) == 0;
        if (spawnParticles) {
            for (var particleBatch : clientData.interval_particles) {
                ParticleHelper.play(world, this, particleBatch);
            }
        }
        for (var particleBatch : clientData.particles) {
            ParticleHelper.play(world, this, particleBatch);
        }

        var presence_sound = cloudData.presence_sound;
        if (!presenceSoundFired && presence_sound != null) {
            var soundEvent = Registries.SOUND_EVENT.get(Identifier.of(presence_sound.id()));
            if (soundEvent != null) {
                ((SoundPlayerWorld) world).playSoundFromEntity(this, soundEvent, SoundCategory.PLAYERS,
                        presence_sound.volume(),
                        presence_sound.randomizedPitch());
                presenceSoundFired = true;
            } else {
                System.out.println("SpellCloud: Failed to find presence sound " + presence_sound.id());
            }
        }

    } else {
        // Server side tick
        if (this.age >= this.timeToLive) {
            this.discard();
            return;
        }
        // Advance the lifecycle phase. Impacts are only performed while ACTIVE — the
        // spawning and despawning phases are warm-up / wind-down, matching SummonedEntity.
        byte phase;
        if (this.age < spawnDuration) {
            phase = PHASE_SPAWNING;
        } else if (this.age >= timeToLive - despawnDuration) {
            phase = PHASE_DESPAWNING;
        } else {
            phase = PHASE_ACTIVE;
        }
        setPhase(phase);
        // Lifetime growth: recompute the radius from the current age and republish it only when it
        // actually changes (i.e. on a growth-step boundary), so rendering/collision follow and sync
        // traffic stays minimal. `radiusForAge` is a no-op unless `growth` is configured.
        float grownRadius = radiusForAge(this.age);
        if (grownRadius != getDataTracker().get(RADIUS_TRACKER)) {
            getDataTracker().set(RADIUS_TRACKER, grownRadius);
            calculateDimensions();
        }
        if (phase == PHASE_ACTIVE && (this.age % cloudData.impact_tick_interval) == 0) {
            // Impact tick due
            var area_impact = cloudData.volume;
            var owner = (LivingEntity) this.getOwner();
            var spellEntry = getSpellEntry();
            if (area_impact != null && owner != null && spellEntry != null) {
                var spell = spellEntry.value();
                var context = this.context;
                if (context == null) {
                    context = new SpellExecution.ImpactContext();
                }
                var performed = SpellImpacts.lookupAndPerformAreaImpact(area_impact, spellEntry, owner,null,
                        this, spell.impacts, context.position(this.getPos()), true, grownRadius);
                if (performed) {
                    onImpactPerformed(owner, world, cloudData, context);
                    if (this.impactCap > 0 && this.impactsPerformed >= this.impactCap) {
                        // A spent cloud winds down through DESPAWNING rather than vanishing on
                        // the spot, so its model gets a phase to animate in. A subclass that
                        // already called `beginDespawn` from `onImpactPerformed` (e.g. to use a
                        // longer, bespoke clip) makes this a no-op.
                        beginDespawn(this.despawnDuration);
                    }
                } else {
                    onImpactFailed(owner, world, cloudData, context);
                }
            }
        }
    }
}

private void setPhase(byte phase) {
    if (getDataTracker().get(PHASE_TRACKER) != phase) {
        getDataTracker().set(PHASE_TRACKER, phase);
        // Fire the wind-down FX exactly on the ACTIVE -> DESPAWNING transition. This is the sole
        // server-side choke point for phase changes (both the age-based expiry in `tick()` and
        // `beginDespawn()` route through here), and the tracker guard makes it run once. Mirrors the
        // spawn FX in CloudPlacer.placeCloud. `despawn_ticks == 0` clouds discard before reaching
        // DESPAWNING, so they get no wind-down FX by design.
        if (phase == PHASE_DESPAWNING) {
            playDespawnFX();
        }
    }
    int endOfPhaseAge = switch (phase) {
        case PHASE_SPAWNING   -> spawnDuration;
        case PHASE_ACTIVE     -> timeToLive - despawnDuration;
        case PHASE_DESPAWNING -> timeToLive;
        default               -> 0;
    };
    getDataTracker().set(END_OF_PHASE_AGE, endOfPhaseAge);
}

private void playDespawnFX() {
    var cloudData = getCloudData();
    if (cloudData == null) {
        return;
    }
    var despawn = cloudData.despawn;
    if (despawn.sound != null) {
        SoundHelper.playSound(getWorld(), this, despawn.sound);
    }
    var despawnVisuals = despawn.visuals.resolved(Fx.Context.NONE);
    ParticleHelper.sendBatches(this, despawnVisuals.particles);
    ModelEffectHelper.spawn(getWorld(), this.getPos(), this.getYaw(), despawnVisuals.models, null);
}

private void setupAnimationStates() {
    spawnAnimationState.setRunning(isSpawning(), this.age);
    boolean despawning = isDespawning();
    if (despawning && !despawnAnimationState.isRunning()) {
        // END_OF_PHASE_AGE = timeToLive during DESPAWNING (a future absolute age). Starting the
        // state there makes getTimeRunning() begin negative, so a renderer can play the spawn clip
        // at speedMultiplier=-1F to scale back out as despawn completes (same trick as SummonedEntity).
        despawnAnimationState.start(getDataTracker().get(END_OF_PHASE_AGE));
    } else if (!despawning) {
        despawnAnimationState.stop();
    }
    idleAnimationState.setRunning(isActive(), this.age);
}

protected void onImpactPerformed(LivingEntity owner, World world, Spell.Delivery.Cloud cloudData, SpellExecution.ImpactContext context) {
    // Server-side call site: `ParticleHelper.play` bottoms out in `World.addParticle`, which is an
    // empty method on anything but ClientWorld — it has to be broadcast instead. Detached (rather
    // than entity-anchored) because a cloud whose `despawn_ticks` is 0 is discarded on this very
    // tick, and the client would resolve the packet's entity id to nothing.
    ParticleHelper.sendBatchesDetached(this, cloudData.impact.resolved(Fx.Context.NONE).particles);
    this.impactsPerformed++;
}

protected void onImpactFailed(LivingEntity owner, World world, Spell.Delivery.Cloud cloudData, SpellExecution.ImpactContext context) {
    // No-op by default; override in subclasses to handle failed impacts (e.g. play a sound).
}

protected void readCustomDataFromNbt(NbtCompound nbt) {
    this.age = nbt.getInt(NBTKey.AGE.key);
    this.timeToLive = nbt.getInt(NBTKey.TIME_TO_LIVE.key);
    this.spawnDuration = nbt.getInt(NBTKey.SPAWN_DURATION.key);
    this.despawnDuration = nbt.getInt(NBTKey.DESPAWN_DURATION.key);
    this.spellId = Identifier.of(nbt.getString(NBTKey.SPELL_ID.key));
    this.dataIndex = nbt.getInt(NBTKey.DATA_INDEX.key);
    if (nbt.contains(NBTKey.CLOUD_MODIFIER.key)) {
        var cm = nbt.getCompound(NBTKey.CLOUD_MODIFIER.key);
        var modifier = new Spell.Modifier.Cloud();
        modifier.radius_add = cm.getFloat("RadiusAdd");
        modifier.growth.radius_step = cm.getFloat("GrowthStep");
        modifier.growth.step_interval = cm.getInt("GrowthInterval");
        modifier.growth.start_tick = cm.getInt("GrowthStart");
        modifier.growth.duration_ticks = cm.getInt("GrowthDuration");
        this.cloudModifier = modifier;
    }
}

protected void writeCustomDataToNbt(NbtCompound nbt) {
    nbt.putInt(NBTKey.AGE.key, this.age);
    nbt.putInt(NBTKey.TIME_TO_LIVE.key, this.timeToLive);
    nbt.putInt(NBTKey.SPAWN_DURATION.key, this.spawnDuration);
    nbt.putInt(NBTKey.DESPAWN_DURATION.key, this.despawnDuration);
    nbt.putString(NBTKey.SPELL_ID.key, this.spellId.toString());
    nbt.putInt(NBTKey.DATA_INDEX.key, this.dataIndex);
    var cm = new NbtCompound();
    cm.putFloat("RadiusAdd", cloudModifier.radius_add);
    cm.putFloat("GrowthStep", cloudModifier.growth.radius_step);
    cm.putInt("GrowthInterval", cloudModifier.growth.step_interval);
    cm.putInt("GrowthStart", cloudModifier.growth.start_tick);
    cm.putInt("GrowthDuration", cloudModifier.growth.duration_ticks);
    nbt.put(NBTKey.CLOUD_MODIFIER.key, cm);
}

protected void initDataTracker(DataTracker.Builder builder) {
    builder.add(SPELL_ID_TRACKER, "");
    builder.add(DATA_INDEX_TRACKER, this.dataIndex);
    builder.add(RADIUS_TRACKER, 0F);
    builder.add(PHASE_TRACKER, PHASE_SPAWNING);
    builder.add(END_OF_PHASE_AGE, 0);
}

@Nullable public Spell.Delivery.Cloud getCloudData() {
    var spellEntry = getSpellEntry();
    if (spellEntry != null) {
        var spell = spellEntry.value();
        return spell.deliver.clouds.get(dataIndex);
    }
    return null;
}

@Nullable public RegistryEntry<Spell> getSpellEntry() {
    return SpellRegistry.from(this.getWorld()).getEntry(this.spellId).orElse(null);
}

private float radiusForAge(int age) {
    var base = baseRadius();
    var cloudData = getCloudData();
    if (cloudData == null) {
        return base;
    }
    var growth = cloudData.growth;
    var mod = cloudModifier.growth;
    boolean baseGrows = growth != null && growth.radius_step != 0F && growth.duration_ticks != 0;

    float step = (growth != null ? growth.radius_step : 0F) + mod.radius_step;
    int baseDuration = growth != null ? growth.duration_ticks : 0;
    // A negative duration on either side is the "whole life" sentinel — it wins over any summed span.
    int duration = (baseDuration < 0 || mod.duration_ticks < 0) ? -1 : baseDuration + mod.duration_ticks;
    int interval = baseGrows ? growth.step_interval : mod.step_interval;
    int startTick = baseGrows ? growth.start_tick : mod.start_tick;

    if (step == 0F || duration == 0 || interval <= 0) {
        return base;
    }
    int elapsed = age - startTick;
    if (elapsed <= 0) {
        return base;
    }
    if (duration > 0) {
        elapsed = Math.min(elapsed, duration);
    }
    int steps = elapsed / interval;
    return Math.max(base + steps * step, 0F);
}

private float baseRadius() {
    var cloudData = getCloudData();
    if (cloudData != null) {
        var radius = cloudData.volume.radius;
        if (context != null) {
            radius = cloudData.volume.combinedRadius(context.power().baseValue());
        }
        return Math.max(radius + cloudModifier.radius_add, 0F);
    } else {
        return 0F;
    }
}

private void chainReactionFrom(Entity target) {
    if (this.perks == null
            || this.perks.chain_reaction_size <= 0
            || this.perks.chain_reaction_triggers <= 0
            || impactHistory.contains(target)) {
        return;
    }
    if (getWorld().isClient) {
        return;
    }
    var spellEntry = this.getSpellEntry();
    if (spellEntry == null) {
        return;
    }
    var position = this.getPos();
    var spawnCount = this.perks.chain_reaction_size;
    var launchVector = new Vec3d(1, 0, 0).multiply(this.getVelocity().length());
    var launchAngle = 360 / spawnCount;
    var launchAngleOffset = random.nextFloat() * launchAngle;

    this.impactHistory.add(target.getId());
    this.perks.chain_reaction_triggers -= 1;
    this.perks.chain_reaction_size += this.perks.chain_reaction_increment;

    for (int i = 0; i < spawnCount; i++) {
        var projectile = new SpellProjectile(getWorld(), (LivingEntity)this.getOwner(),
                position.getX(), position.getY(), position.getZ(),
                this.getBehaviour(), spellEntry, context, this.perks.copy());

        var angle = launchAngle * i + launchAngleOffset;
        projectile.setVelocity(launchVector.rotateY((float) Math.toRadians(angle)));
        projectile.range = this.range;
        ProjectileUtil.setRotationFromVelocity(projectile, 0.2F);
        projectile.impactHistory = new HashSet<>(this.impactHistory);
        getWorld().spawnEntity(projectile);
    }
}

protected void onEntityHit(EntityHitResult entityHitResult) {
    if (!getWorld().isClient) {
        var target = entityHitResult.getEntity();
        if (target != null
                && !impactHistory.contains(target.getId())
                && this.getOwner() != null
                && this.getOwner() instanceof LivingEntity caster) {
            setFollowedTarget(null);
            var context = this.context;
            if (context == null) {
                context = new SpellExecution.ImpactContext();
                var spell = this.getSpellEntry().value();
                if (getOwner() instanceof PlayerEntity player && spell != null)  {
                    context = context.power(SpellPower.getSpellPower(spell.school, player));
                }
            }
            if (context.power() == null) {
                this.kill();
                return;
            }

            var prevProjectilePos = new Vec3d(this.prevX, this.prevY, this.prevZ);
            var hitVector = entityHitResult.getPos().subtract(prevProjectilePos).normalize().multiply(this.getWidth() * 0.5F);
            var hitPosition = entityHitResult.getPos().subtract(hitVector);

            var performed = SpellImpacts.projectileImpact(caster, this, target, this.getSpellEntry(), context.position(hitPosition));
            if (performed) {
                chainReactionFrom(target);
                if (ricochetFrom(target, caster)) {
                    return;
                }
                if (pierced(target)) {
                    return;
                }
                this.kill();
            }
        }
    }
}

protected boolean ricochetFrom(Entity target, LivingEntity caster) {
    if (this.perks == null
            || this.perks.ricochet <= 0) {
        return false;
    }
    impactHistory.add(target.getId());

    // Find next target
    var box = this.getBoundingBox().expand(
            this.perks.ricochet_range,
            this.perks.ricochet_range,
            this.perks.ricochet_range);
    var spell = this.getSpellEntry().value();
    var intents = SpellIntents.impactIntents(spell);
    Predicate<Entity> intentMatches = (entity) -> {
        boolean intentAllows = false;
        for (var intent: intents) {
            intentAllows = intentAllows || EntityRelations.actionAllowed(SpellTarget.FocusMode.AREA, intent, caster, entity);
        }
        return intentAllows;
    };
    var otherTargets = this.getWorld().getOtherEntities(this, box, (entity) -> {
        return entity.isAttackable()
                && entity instanceof LivingEntity // Avoid targeting unliving entities like other projectiles
                && !impactHistory.contains(entity.getId())
                && intentMatches.test(entity)
                && !entity.getPos().equals(target.getPos());
    });
    if (otherTargets.isEmpty()) {
        this.setFollowedTarget(null);
        return false;
    }

    otherTargets.sort(Comparator.comparingDouble(o -> o.squaredDistanceTo(target)));

    // Set trajectory
    var newTarget = otherTargets.get(0);
    this.setPosition(target.getPos().add(0, target.getHeight() * 0.5F, 0));
    this.setFollowedTarget(newTarget);

    var distanceVector = (newTarget.getPos().add(0, newTarget.getHeight() / 2F, 0))
            .subtract(this.getPos().add(0, this.getHeight() / 2F, 0));
    var newVelocity = distanceVector.normalize().multiply(this.getVelocity().length());
    this.setVelocity(newVelocity);
    this.velocityDirty = true;

    this.perks.ricochet -= 1;
    if (this.perks.bounce_ricochet_sync) {
        this.perks.bounce -= 1;
    }
    return true;
}

private boolean pierced(Entity target) {
    if (this.perks == null
            || this.perks.pierce <= 0) {
        return false;
    }
    // Save
    impactHistory.add(target.getId());
    setFollowedTarget(null);
    this.perks.pierce -= 1;

    // Modify velocity by a tiny, non zero amount
    // to enforce velocity update on the client.
    // (Otherwise the projectile is going crazy on the client)
    var tiny = 0.01 * ((-1) * (this.perks.pierce % 2));
    this.setVelocity(this.getVelocity().multiply(1 + tiny));
    this.velocityDirty = true;

    return true;
}

