public static void init() {
    // Config stage
    PayloadTypeRegistry.configurationS2C().register(Packets.ConfigSync.PACKET_ID, Packets.ConfigSync.CODEC);
    PayloadTypeRegistry.configurationS2C().register(Packets.SpellRegistrySync.PACKET_ID, Packets.SpellRegistrySync.CODEC);
    PayloadTypeRegistry.configurationC2S().register(Packets.Ack.PACKET_ID, Packets.Ack.CODEC);

    ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
        // This if block is required! Otherwise the client gets stuck in connection screen
        // if the client cannot handle the packet.
        if (ServerConfigurationNetworking.canSend(handler, Packets.ConfigSync.ID)) {
            handler.addTask(new ConfigurationTask(SpellEngineMod.config));
        } else {
            handler.disconnect(Text.literal("Network configuration task not supported: " + ServerNetwork.CONFIG_TASK_NAME));
        }
    });
    ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
        if (ServerConfigurationNetworking.canSend(handler, Packets.SpellRegistrySync.ID)) {
            if (SpellAssignments.encoded.isEmpty()) {
                throw new AssertionError("Spell registry is empty!");
            }
            handler.addTask(new SpellRegistrySyncTask(SpellAssignments.encoded));
        } else {
            handler.disconnect(Text.literal("Network configuration task not supported: " + ServerNetwork.SPELL_REGISTRY_TASK_NAME));
        }
    });
    ServerConfigurationNetworking.registerGlobalReceiver(Packets.Ack.PACKET_ID, (packet, context) -> {
        // Warning: if you do not call completeTask, the client gets stuck!
        if (packet.code().equals(ServerNetwork.CONFIG_TASK_NAME)) {
            context.networkHandler().completeTask(ConfigurationTask.KEY);
        }
        if (packet.code().equals(ServerNetwork.SPELL_REGISTRY_TASK_NAME)) {
            context.networkHandler().completeTask(SpellRegistrySyncTask.KEY);
        }
    });

    // Play stage
    PayloadTypeRegistry.playC2S().register(Packets.CastRequest.PACKET_ID, Packets.CastRequest.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.TargetStream.PACKET_ID, Packets.TargetStream.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.CastInput.PACKET_ID, Packets.CastInput.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.AttackPerform.PACKET_ID, Packets.AttackPerform.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.AttackFxBroadcast.PACKET_ID, Packets.AttackFxBroadcast.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellCooldown.PACKET_ID, Packets.SpellCooldown.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellCooldownSync.PACKET_ID, Packets.SpellCooldownSync.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellMessage.PACKET_ID, Packets.SpellMessage.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.ParticleEffects.PACKET_ID, Packets.ParticleEffects.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellAnimation.PACKET_ID, Packets.SpellAnimation.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellContainerSync.PACKET_ID, Packets.SpellContainerSync.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.AttackAvailable.PACKET_ID, Packets.AttackAvailable.CODEC);

    ServerPlayNetworking.registerGlobalReceiver(Packets.CastRequest.PACKET_ID, (packet, context) ->
            ServerNetwork.handleCastRequest(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.TargetStream.PACKET_ID, (packet, context) ->
            ServerNetwork.handleTargetStream(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.CastInput.PACKET_ID, (packet, context) ->
            ServerNetwork.handleCastInput(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.AttackFxBroadcast.PACKET_ID, (packet, context) ->
            ServerNetwork.handleAttackFxBroadcast(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.AttackPerform.PACKET_ID, (packet, context) ->
            ServerNetwork.handleAttackPerform(packet, context.server(), context.player()));
}

public static void init() {
    // Config stage
    ClientConfigurationNetworking.registerGlobalReceiver(Packets.ConfigSync.PACKET_ID, (packet, context) -> {
        ClientNetwork.handleConfigSync(packet);
        context.responseSender().sendPacket(new Packets.Ack(ServerNetwork.CONFIG_TASK_NAME));
    });
    ClientConfigurationNetworking.registerGlobalReceiver(Packets.SpellRegistrySync.PACKET_ID, (packet, context) -> {
        ClientNetwork.handleSpellRegistrySync(packet);
        context.responseSender().sendPacket(new Packets.Ack(ServerNetwork.SPELL_REGISTRY_TASK_NAME));
    });

    // Play stage
    ClientPlayNetworking.registerGlobalReceiver(Packets.ParticleEffects.PACKET_ID, (packet, context) ->
            ClientNetwork.handleParticleEffects(packet));
    ClientPlayNetworking.registerGlobalReceiver(Packets.SpellAnimation.PACKET_ID, (packet, context) ->
            ClientNetwork.handleSpellAnimation(packet));
    ClientPlayNetworking.registerGlobalReceiver(Packets.SpellCooldown.PACKET_ID, (packet, context) ->
            ClientNetwork.handleSpellCooldown(packet));
    ClientPlayNetworking.registerGlobalReceiver(Packets.SpellMessage.PACKET_ID, (packet, context) ->
            ClientNetwork.handleSpellMessage(packet));
    ClientPlayNetworking.registerGlobalReceiver(Packets.SpellCooldownSync.PACKET_ID, (packet, context) ->
            ClientNetwork.handleSpellCooldownSync(packet));
    ClientPlayNetworking.registerGlobalReceiver(Packets.SpellContainerSync.PACKET_ID, (packet, context) ->
            ClientNetwork.handleSpellContainerSync(packet));
    ClientPlayNetworking.registerGlobalReceiver(Packets.AttackAvailable.PACKET_ID, (packet, context) ->
            ClientNetwork.handleAttackAvailable(packet));
}

public NeoForgeMod(IEventBus modBus) {
    // Run our common setup.
    SpellEngineMod.init();
    NeoForgeCompatFeatures.init();
    modBus.addListener(RegisterEvent.class, NeoForgeMod::register);
    // Summoned-entity default attributes are buffered by content mods during entity registration
    // and supplied here, the only point NeoForge accepts them. Works for every mod's summons since
    // the buffer is static and this event accepts any entity type.
    modBus.addListener(EntityAttributeCreationEvent.class, SummonedEntityAttributeRegistrar::onCreateAttributes);
    // Synced datapack registries buffered during common init (replaces DynamicRegistries.registerSynced).
    modBus.addListener(DataPackRegistryEvent.NewRegistry.class, SyncedDataRegistrar::onNewRegistry);
    // Creative-tab entries buffered during common init (replaces Fabric's ItemGroupEvents).
    modBus.addListener(BuildCreativeModeTabContentsEvent.class, NeoForgeMod::onBuildCreativeTabContents);
}

public static void register(RegisterEvent event) {
    event.register(RegistryKeys.ENTITY_TYPE, reg -> {
        SpellEngineMod.registerEntityTypes();
    });
    event.register(RegistryKeys.PARTICLE_TYPE, reg -> {
        SpellEngineParticles.register();
    });
    event.register(RegistryKeys.STATUS_EFFECT, reg -> {
        SpellEngineEffects.register();
    });
    event.register(RegistryKeys.ITEM, reg -> {
        SpellEngineItems.register();
    });
    event.register(RegistryKeys.SOUND_EVENT, reg -> {
        SpellEngineSounds.register();
    });
    event.register(RegistryKeys.BLOCK, reg -> {
        // Warning this registers not only blocks!
        // May cause issues, cba for now :)
        SpellEngineMod.registerSpellBinding();
    });
    event.register(RegistryKeys.CRITERION, reg -> {
        SpellEngineMod.registerCriteria();
    });
}

public static void onClientSetup(FMLClientSetupEvent event) {
    SpellEngineClient.init();

    // Game-bus client events (tooltip lines, beam world-render pass) — subscribed here since this
    // class is on the mod bus; the callbacks live in loader-neutral common code.
    NeoForge.EVENT_BUS.addListener(ItemTooltipEvent.class, tooltip ->
            SpellEngineClient.addTooltipLines(tooltip.getItemStack(), tooltip.getFlags(), tooltip.getToolTip()));
    NeoForge.EVENT_BUS.addListener(RenderLevelStageEvent.class, render -> {
        if (render.getStage() == RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS) {
            BeamRenderer.renderAfterTranslucent(render.getPoseStack(), render.getCamera(), render.getPartialTick().getTickDelta(true));
        }
    });
    event.enqueueWork(SpellEngineClient::onClientStarted);

    ModLoadingContext.get().registerExtensionPoint(IConfigScreenFactory.class, () -> (modContainer, parent) -> new ConfigMenuScreen(parent));
}
